import * as THREE from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial
} from 'three/webgpu';
import {
  uv,
  texture,
  mix,
  vec3
} from 'three/tsl';
import { gsap } from 'gsap';

type NodeConfig = {
  imageUrl?: string;
  depthMapUrl?: string;
  textContent?: Array<{
    text: string;
    role?: string;
    typography?: {
      fontSize?: number;
    };
  }>;
  intent?: {
    visualSpec?: {
      textContent?: NodeConfig['textContent'];
      colors?: Record<string, string>;
    };
  };
  cinematicPrimitives?: Array<{
    name: string;
    params?: Record<string, unknown>;
    trigger?: string;
  }>;
};

type NodeContext = {
  THREE: typeof THREE;
  textureLoader: {
    loadTexture(url: string): Promise<THREE.Texture>;
  };
  glbLoader: {
    loadGLB(url: string): Promise<any>;
  };
  videoLoader?: {
    loadVideo(url: string): Promise<THREE.Texture>;
  };
  fontAtlas: {
    createText(
      content: string,
      opts?: {
        fontSize?: number;
        color?: THREE.ColorRepresentation;
        align?: 'left' | 'center' | 'right';
        maxWidthPx?: number;
        letterSpacingPx?: number;
      }
    ): THREE.Object3D;
  };
  primitives: Record<
    string,
    (
      target: THREE.Object3D,
      params?: Record<string, unknown>
    ) => { timeline?: gsap.core.Timeline; cleanup?: () => void }
  >;
  emit(event: string, payload?: unknown): void;
  tier?: 'T0' | 'T1' | 'T2';
};

export default function createNode(
  config: NodeConfig,
  ctx: NodeContext
): THREE.Object3D {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    CircleGeometry,
    Vector3,
    Color,
    PointLight
  } = ctx.THREE;

  const root = new Group();
  root.name = 'features-stat-tile';

  const resources: Array<{ dispose?: () => void }> = [];
  const primitiveCleanups: Array<() => void> = [];
  const timelines: gsap.core.Timeline[] = [];

  const ink = '#16161d';
  const paper = '#e8ecf2';
  const accent = '#ff2a38';
  const surface = '#0b0b10';

  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.18, 0.18, 0.21),
      uv().y
    ),
    uv().y
  );

  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    backdropMaterial
  );
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdrop.geometry, backdrop.material);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: new Color(0x000000),
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });

  const contactShadow = new Mesh(
    new CircleGeometry(1.7, 64),
    shadowMaterial
  );
  contactShadow.name = 'radial-contact-shadow';
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.scale.set(1.35, 0.62, 1);
  contactShadow.position.set(0, -0.82, -0.18);
  root.add(contactShadow);
  resources.push(contactShadow.geometry, contactShadow.material);

  const card = new Group();
  card.name = 'machined-stat-card';
  root.add(card);

  const cardMaterial = new MeshStandardNodeMaterial({
    color: new Color(surface),
    roughness: 0.62,
    metalness: 0.48
  });

  const cardBody = new Mesh(
    new BoxGeometry(2.45, 1.48, 0.16, 4, 4, 2),
    cardMaterial
  );
  cardBody.name = 'machined-surface';
  cardBody.position.z = 0;
  card.add(cardBody);
  resources.push(cardBody.geometry, cardBody.material);

  const innerMaterial = new MeshStandardNodeMaterial({
    color: new Color(ink),
    roughness: 0.58,
    metalness: 0.4
  });

  const innerPanel = new Mesh(
    new BoxGeometry(2.18, 1.21, 0.035, 2, 2, 1),
    innerMaterial
  );
  innerPanel.name = 'recessed-card-panel';
  innerPanel.position.set(0, 0, 0.1);
  card.add(innerPanel);
  resources.push(innerPanel.geometry, innerPanel.material);

  const edgeMaterial = new MeshStandardNodeMaterial({
    color: new Color(accent),
    roughness: 0.52,
    metalness: 0.32,
    emissive: new Color(accent),
    emissiveIntensity: 0.42
  });

  const accentEdge = new Mesh(
    new BoxGeometry(0.035, 1.22, 0.055),
    edgeMaterial
  );
  accentEdge.name = 'focus-accent-edge';
  accentEdge.position.set(-1.075, 0, 0.145);
  accentEdge.visible = false;
  card.add(accentEdge);
  resources.push(accentEdge.geometry, accentEdge.material);

  const topRail = new Mesh(
    new BoxGeometry(1.75, 0.025, 0.045),
    edgeMaterial
  );
  topRail.name = 'machined-accent-rail';
  topRail.position.set(0.1, 0.53, 0.145);
  topRail.scale.x = 0.72;
  card.add(topRail);
  resources.push(topRail.geometry, topRail.material);

  const imageMaterial = new MeshStandardNodeMaterial({
    color: new Color(paper),
    roughness: 0.56,
    metalness: 0.18
  });

  const imagePlane = new Mesh(
    new PlaneGeometry(2.12, 1.15, 64, 64),
    imageMaterial
  );
  imagePlane.name = 'parallax-textured-surface';
  imagePlane.position.set(0.02, 0, 0.125);
  card.add(imagePlane);
  resources.push(imagePlane.geometry, imagePlane.material);

  const keyLight = new PointLight(0xe8ecf2, 0.9, 5);
  keyLight.name = 'local-product-key';
  keyLight.position.set(-1.4, 1.6, 2.4);
  root.add(keyLight);

  const rimLight = new PointLight(0xff2a38, 0.62, 4);
  rimLight.name = 'local-red-rim';
  rimLight.position.set(1.7, -0.7, 1.8);
  root.add(rimLight);

  const imageUrl = config.imageUrl;
  const depthMapUrl = config.depthMapUrl;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((loadedTexture) => {
      imageMaterial.colorNode = texture(loadedTexture);
      imageMaterial.needsUpdate = true;
      resources.push(loadedTexture);
    });
  }

  if (depthMapUrl) {
    ctx.textureLoader.loadTexture(depthMapUrl).then((depthTexture) => {
      imageMaterial.displacementNode = texture(depthTexture).r;
      imageMaterial.displacementScale = 0.075;
      imageMaterial.needsUpdate = true;
      resources.push(depthTexture);
    });
  }

  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of items) {
    if (typeof item.text !== 'string') continue;
    const label = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 24,
      color: paper,
      align: 'center'
    });
    label.position.set(0, -0.02, 0.19);
    label.renderOrder = 4;
    card.add(label);
  }

  const entrance = gsap.timeline();
  entrance.fromTo(
    card.position,
    { y: 0.4 },
    { y: 0, duration: 0.7, ease: 'power3.out' }
  );
  entrance.fromTo(
    card.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.42, ease: 'power4.out' },
    0
  );
  entrance.to(card.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.48,
    ease: 'power4.out'
  });
  timelines.push(entrance);

  const hoverLift = gsap.timeline({ paused: true });
  hoverLift.to(card.position, {
    y: 0.15,
    duration: 0.3,
    ease: 'power3.out'
  });
  hoverLift.to(
    card.rotation,
    {
      x: -0.035,
      y: 0.045,
      duration: 0.3,
      ease: 'power3.out'
    },
    0
  );
  timelines.push(hoverLift);

  const handlers: Record<string, (...args: any[]) => void> = {
    hover: (active = true) => {
      if (active) hoverLift.play();
      else hoverLift.reverse();
    },
    click: () => {
      gsap.fromTo(
        card.scale,
        { x: 0.97, y: 0.97, z: 0.97 },
        {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.12,
          ease: 'back.out(2)'
        }
      );
      ctx.emit('hub-features.select', {
        node: 'features-stat-tile'
      });
    },
    focus: () => {
      accentEdge.visible = true;
    },
    blur: () => {
      accentEdge.visible = false;
    }
  };

  root.userData.handlers = handlers;

  for (const primitive of config.cinematicPrimitives ?? []) {
    const apply = ctx.primitives?.[primitive.name];
    if (!apply) continue;
    const result = apply(root, primitive.params ?? {});
    if (result?.timeline) timelines.push(result.timeline);
    if (result?.cleanup) primitiveCleanups.push(result.cleanup);
  }

  root.userData.cleanup = () => {
    timelines.forEach((timeline) => timeline.kill());
    primitiveCleanups.forEach((cleanup) => cleanup());

    root.traverse((object: any) => {
      if (object.geometry?.dispose) object.geometry.dispose();
      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];
        materials.forEach((material: any) => material.dispose?.());
      }
    });

    resources.forEach((resource) => resource.dispose?.());
  };

  return root;
}
